\begin{align*}
   t + s = t + \frac{1}{t} = 7. \end{align*}
We need $t^2 + s^2$. By iterating the equation,
\begin{align*}
   (s - t)^2 &= s^2 - 2st + t^2\\
   &= s^2 - 2 + t^2 = \frac{1}{t^2} - 2 + t^2 = \frac{(t^2 - 2)^2 - 2}{t^2}\\
   &= \frac{(t^2 - 2)^2}{t^2} - 2.
\end{align*}
Thus,
\begin{align*}
   7^2 &= t^2 + s^2 = (t + s)^2 + (s - t)^2 \\
   &= t^2 + s^2 + t^2 + s^2 - 4 = 2(t^2 + s^2)  - 4\\
   &\Longrightarrow \boxed{t^2 + s^2 = 26}.
  \end{align*}
So,
\begin{align*}
   \boxed{(\log_y x)^2 + (\log_x y)^2} = 26.
\end{align*}
